Using Bottom-Up DP (Tabulation) - O(n) Time and O(n) SpaceThe idea is to create a 1-D array, fill values for first three stairs and compute the values from 3 to n using the previous three results. For i=3 to n, do dp[i] = dp[i-1] + dp[i-2] + dp[i-3]. Below is the implementation of the above approach:
            C++

    // C++ program to count number of
// ways to reach nth stair.
#include <bits/stdc++.h>
using namespace std;

int countWays(int n) {

    // Base case for 0th and 1st stair
    if (n == 0 || n == 1)
        return 1;

    // base case for 2nd stair
    if (n == 2)
        return 2;

    // Initializing a matrix of size n+1
    vector<int> dp(n + 1);

    // insert ans values for 0,1,2 stair
    dp[0] = 1;
    dp[1] = 1;
    dp[2] = 2;

    // building dp in bottom up manner
    for (int i = 3; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3];
    }

    return dp[n];
}

int main() {

    int n = 4;
    cout << countWays(n) << endl;
    return 0;
}


