Using Matrix Exponentiation - O(log n) Time and O(1) SpaceThe recurrence relation for a given step is given as countWays(n) = countWays(n-1) + countWays(n-2) + countWays(n-3) starting with countWays(0)=1, countWays(1)=1, countWays(2)=2.Refer to Matrix Exponentiation to understand how matrix exponentiation works.Below is the implementation of the above approach:
            C++

    // C++ program to count number of
// ways to reach nth stair.
#include <bits/stdc++.h>
using namespace std;

// Function to multiply two 3x3 matrices
void multiply(vector<vector<int> >& a,
              vector<vector<int> >& b) {

    // Matrix to store the result
    vector<vector<int> > c(3, vector<int>(3));

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                c[i][j]
                    = (c[i][j] + ((a[i][k]) * (b[k][j])));
            }
        }
    }

    // Copy the result back to the first matrix
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            a[i][j] = c[i][j];
        }
    }
}

// Function to calculate (Matrix M) ^ expo
vector<vector<int> >
power(vector<vector<int> > m, int expo) {

    // Initialize result with identity matrix
    vector<vector<int> > ans
        = { { 1, 0, 0 }, { 0, 1, 0 }, { 0, 0, 1 } };

    // Fast Exponentiation
    while (expo) {
        if (expo & 1)
            multiply(ans, m);
        multiply(m, m);
        expo >>= 1;
    }

    return ans;
}

// function to count number of
// ways to reach nth stair.
int countWays(int n) {

    // base condition
    if (n == 0 || n == 1)
        return 1;

    // Matrix M to generate the next step value.
    vector<vector<int> > m
        = { { 1, 1, 1 }, { 1, 0, 0 }, { 0, 1, 0 } };

    // first 3 values of steps are:
    // findWays(0) = 1
    // findWays(1) = 1
    // findWays(2) = 2
    // f = {{findWays(2), 0, 0}, {findWays(1), 0, 0}, 
    //  {findWays(0), 0,0}}
    vector<vector<int> > f
        = { { 2, 0, 0 }, { 1, 0, 0 }, { 1, 0, 0 } };

    vector<vector<int> > res = power(m, n - 2);
    multiply(res, f);

    return res[0][0];
}

int main() {

    int n = 4;
    cout << countWays(n) << endl;
    return 0;
}


